operation.document:
query GetIssueAgentSessions($issueId: String!) {
  issue(id: $issueId) {
    comments(first: 100) {
      nodes {
        agentSession {
          id
          status
          type
          createdAt
          startedAt
          endedAt
          summary
          creator {
            name
          }
          appUser {
            name
          }
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
}
